<script setup lang="ts">
import { ref } from 'vue'
import { useFullCourse } from '../fullCourseStore'
import { equipmentIds,type Equipment } from '../domain'
import { componentNames,expectedPoints,type ArchitectureEdge,type ComponentId } from '../fullCourseDomain'
import { kindLabels } from '../sceneGraph'
const course=useFullCourse(),root=ref<HTMLElement>()
function focusAsset(id:Equipment){const field=root.value?.querySelector<HTMLElement>(`[data-edit-asset="${id}"] input, [data-edit-asset="${id}"] select`);field?.scrollIntoView({block:'center'});field?.focus({preventScroll:true})}
defineExpose({focusAsset})
const edge=ref<ArchitectureEdge>({from:'source',to:'gateway',access:'read'})
const coordinates:Record<ComponentId,[number,number]>={source:[80,55],gateway:[280,55],storage:[480,55],knowledge:[80,185],ai:[280,185],twin:[480,185]}
function addEdge(){if(course.saved.config.architecture.edges.length>=40){course.message='连接最多40条。';return}course.saved.config.architecture.edges.push({...edge.value})}
</script>
<template><div ref="root" class="full-editor">
 <template v-if="course.saved.step===1"><h3>教学需求单</h3><p>监测教学储罐、泵与换热器，使台账、测点和三维对象一致；发现数据问题并追溯事件；用资料引用和检测评测验证AI辅助。所有修改均在教学环境进行。</p>
 <div v-for="r in course.saved.config.requirements" :key="r.kind" class="full-form-row"><h4>{{ r.kind }}需求</h4><label class="field"><span>{{ r.kind }}需求描述</span><textarea v-model="r.need" :aria-label="r.kind+'需求描述'" maxlength="10000" rows="2" /></label><label class="field"><span>{{ r.kind }}验收条件</span><textarea v-model="r.acceptance" :aria-label="r.kind+'验收条件'" maxlength="10000" rows="2" placeholder="写出输入、操作和能够核对的结果" /></label></div></template>
 <template v-else-if="course.saved.step===2"><h3>组件连接与环境边界</h3>
 <div class="full-diagram"><svg viewBox="0 0 570 245" role="img" aria-label="学生配置的系统架构图"><defs><marker id="full-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#5c9182" /></marker></defs><line v-for="(e,i) in course.saved.config.architecture.edges" :key="i" :x1="coordinates[e.from][0]" :y1="coordinates[e.from][1]" :x2="coordinates[e.to][0]" :y2="coordinates[e.to][1]" stroke="#5c9182" stroke-width="2" marker-end="url(#full-arrow)"/><g v-for="(name,id) in componentNames" :key="id"><rect :x="coordinates[id][0]-69" :y="coordinates[id][1]-23" width="138" height="46" rx="6" fill="#f0f7f3" stroke="#a8c7ba"/><text :x="coordinates[id][0]" :y="coordinates[id][1]+5" text-anchor="middle" fill="#254f41" font-size="13">{{ name }}</text></g></svg></div>
 <div class="full-grid-two"><label v-for="(name,id) in componentNames" :key="id" class="field"><span>{{ name }}所在环境</span><select v-model="course.saved.config.architecture.scopes[id]" :aria-label="name+'所在环境'"><option value="production">生产侧</option><option value="teaching">教学沙盒</option></select></label></div>
 <div class="full-edge-form"><label class="field"><span>连接起点</span><select v-model="edge.from" aria-label="连接起点"><option v-for="(name,id) in componentNames" :key="id" :value="id">{{ name }}</option></select></label><label class="field"><span>连接终点</span><select v-model="edge.to" aria-label="连接终点"><option v-for="(name,id) in componentNames" :key="id" :value="id">{{ name }}</option></select></label><label class="field"><span>读写方式</span><select v-model="edge.access" aria-label="读写方式"><option value="read">读取（沿箭头供数）</option><option value="write">写入目标组件</option></select></label><button class="btn" @click="addEdge">添加连接</button></div>
 <ul class="full-edge-list"><li v-for="(e,i) in course.saved.config.architecture.edges" :key="i">{{ componentNames[e.from] }} → {{ componentNames[e.to] }} · {{ e.access==='read'?'读取':'写入' }} <button class="core-link" :aria-label="'删除第'+(i+1)+'条连接'" @click="course.saved.config.architecture.edges.splice(i,1)">删除</button></li></ul>
 <label class="field"><span>架构设计理由</span><textarea v-model="course.saved.config.architecture.rationale" aria-label="架构设计理由" maxlength="10000" rows="3" /></label></template>
 <template v-else-if="course.saved.step===3"><h3>工厂—区域—车间—设备层级</h3><p class="core-small">可以选择非法父节点测试反馈；错误草稿会保存，合法性校验通过后才形成成果。</p>
 <div v-for="n in course.saved.config.layout.nodes" :key="n.id" class="full-form-row" :data-edit-asset="n.assetId" :class="{'is-scene-selected':course.sceneView.selectedId===n.id}"><h4>{{ kindLabels[n.kind] }} · {{ n.id }}</h4><div class="full-grid-two"><label class="field"><span>{{ n.id }}名称</span><input v-model="n.name" :aria-label="n.id+'名称'" maxlength="40" /></label><label class="field"><span>{{ n.id }}父节点</span><select v-model="n.parentId" :aria-label="n.id+'父节点'"><option :value="null">无父节点</option><option v-for="parent in course.saved.config.layout.nodes" :key="parent.id" :value="parent.id">{{ parent.name }}（{{ kindLabels[parent.kind] }}）</option></select></label></div></div></template>
 <template v-else-if="course.saved.step===4"><h3>资产台账</h3><div v-for="a in course.saved.config.assets" :key="a.id" class="full-form-row" :data-edit-asset="a.id" :class="{'is-scene-selected':course.sceneView.selectedId==='model-'+a.id}"><h4>稳定资产ID：{{ a.id }}</h4><div class="full-grid-two"><label class="field"><span>{{ a.id }}设备名称</span><input v-model="a.name" :aria-label="a.id+'设备名称'" maxlength="40" /></label><label class="field"><span>{{ a.id }}唯一编码</span><input v-model="a.code" :aria-label="a.id+'唯一编码'" maxlength="24" /></label></div></div></template>
 <template v-else-if="course.saved.step===5"><h3>三类测点字典</h3><div v-for="id in equipmentIds" :key="id" class="full-form-row" :data-edit-asset="id" :class="{'is-scene-selected':course.sceneView.selectedId==='model-'+id}"><h4>{{ expectedPoints[id].name }}</h4><div class="full-grid-two"><label class="field"><span>{{ id }}字段</span><input v-model="course.saved.config.dictionary[id].field" :aria-label="id+'字段'" maxlength="100" /></label><label class="field"><span>{{ id }}类型</span><select v-model="course.saved.config.dictionary[id].type" :aria-label="id+'类型'"><option value="number">number</option><option value="string">string</option></select></label><label class="field"><span>{{ id }}单位</span><select v-model="course.saved.config.dictionary[id].unit" :aria-label="id+'单位'"><option v-for="unit in ['A','mA','%','℃']" :key="unit">{{ unit }}</option></select></label><label class="field"><span>{{ id }}量程下限</span><input v-model.number="course.saved.config.dictionary[id].min" :aria-label="id+'量程下限'" type="number" /></label><label class="field"><span>{{ id }}量程上限</span><input v-model.number="course.saved.config.dictionary[id].max" :aria-label="id+'量程上限'" type="number" /></label><label class="field"><span>{{ id }}质量码（英文逗号分隔）</span><input v-model="course.saved.config.dictionary[id].qualityCodes" :aria-label="id+'质量码'" maxlength="300" /></label></div></div></template>
 <template v-else-if="course.saved.step===6"><h3>局部位置与实体核对</h3><p class="core-small">位置相对于所属车间的默认设备位置，单位为教学米。归属修改请返回步骤03，修改后相关成果须复验。</p><div v-for="id in equipmentIds" :key="id" class="full-form-row" :data-edit-asset="id" :class="{'is-scene-selected':course.sceneView.selectedId==='model-'+id}"><h4>{{ course.saved.config.assets.find(a=>a.id===id)?.name }} · {{ course.path('model-'+id) }}</h4><div class="full-grid-three"><label v-for="(axis,i) in ['x','y','z']" :key="axis" class="field"><span>{{ id }}局部{{ axis }}</span><input v-model.number="course.saved.config.positions[id][i]" :aria-label="id+'局部'+axis" type="number" step="0.1" /></label></div></div></template>
 <template v-else-if="course.saved.step===7"><h3>模型 → 资产 → 字段 → 数据源</h3><div v-for="id in equipmentIds" :key="id" class="full-form-row" :data-edit-asset="id" :class="{'is-scene-selected':course.sceneView.selectedId==='model-'+id}"><h4>{{ course.saved.config.layout.nodes.find(n=>n.id==='model-'+id)?.name }} · model-{{ id }}</h4><div class="full-grid-three"><label class="field"><span>{{ id }}绑定资产</span><select v-model="course.saved.config.mappings[id].assetId" :aria-label="id+'绑定资产'"><option value="">未绑定</option><option v-for="a in course.saved.config.assets" :key="a.id" :value="a.id">{{ a.code }} · {{ a.name }}</option></select></label><label class="field"><span>{{ id }}绑定字段</span><select v-model="course.saved.config.mappings[id].field" :aria-label="id+'绑定字段'"><option value="">未选择</option><option v-for="other in equipmentIds" :key="other" :value="course.saved.config.dictionary[other].field">{{ course.saved.config.dictionary[other].field }} / {{ course.saved.config.dictionary[other].unit }}</option></select></label><label class="field"><span>{{ id }}数据源</span><select v-model="course.saved.config.mappings[id].sourceId" :aria-label="id+'数据源'"><option value="">未选择</option><option v-for="other in equipmentIds" :key="other" :value="'teaching-'+other">teaching-{{ other }}</option></select></label></div></div></template>
</div></template>
